/* "Find Your Way" floor directory (directory/index.html, generated by tools/build_pages.py).
   Floors are WAI-ARIA tabs (arrow keys, Home/End); #floor-2 style links open a floor; the search highlights
   the floors that have a match and jumps to the first one. Without JavaScript every floor's list stays visible. */
(function () {
    var tabs = [].slice.call(document.querySelectorAll('.pdh-bldg [role="tab"]'));
    if (!tabs.length) return;
    var form = document.querySelector('[data-pdh-dir-search]');
    var input = form.elements.q;
    var status = document.querySelector('[data-pdh-dir-status]');

    // Lowercase and strip accents; mirrors fold() in tools/build_pages.py.
    function fold(text) {
        return (text || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
    }
    function panelOf(tab) { return document.getElementById(tab.getAttribute('aria-controls')); }

    // updateUrl: only on the visitor's own choices; writing a #hash on load makes the site's script scroll to it.
    function select(tab, focus, updateUrl) {
        tabs.forEach(function (t) {
            var on = t === tab;
            t.setAttribute('aria-selected', on ? 'true' : 'false');
            t.tabIndex = on ? 0 : -1;
            panelOf(t).hidden = !on;
        });
        if (updateUrl) history.replaceState(null, '', location.pathname + location.search + '#' + tab.getAttribute('aria-controls'));
        if (focus) tab.focus();
    }

    tabs.forEach(function (tab, i) {
        tab.addEventListener('click', function () { select(tab, false, true); });
        tab.addEventListener('keydown', function (ev) {
            var next = { ArrowUp: tabs[i - 1], ArrowDown: tabs[i + 1], Home: tabs[0], End: tabs[tabs.length - 1] }[ev.key];
            if (next) { ev.preventDefault(); select(next, true, true); }
        });
    });

    function search() {
        var terms = fold(input.value).split(/\s+/).filter(Boolean);
        var floorsHit = [], hits = 0;
        tabs.forEach(function (tab) {
            var cards = [].slice.call(panelOf(tab).querySelectorAll('.pdh-dir__card'));
            var n = 0;
            cards.forEach(function (card) {
                var match = terms.length && terms.every(function (t) { return card.dataset.search.indexOf(t) !== -1; });
                card.classList.toggle('is-match', !!match);
                card.classList.toggle('is-dim', terms.length > 0 && !match);
                if (match) n++;
            });
            tab.classList.toggle('has-match', n > 0);
            tab.classList.toggle('is-dim', terms.length > 0 && n === 0);
            tab.querySelector('[data-count]').textContent = terms.length ? n : cards.length;
            if (n) { floorsHit.push(tab); hits += n; }
        });
        if (!terms.length) { status.textContent = ''; return; }
        if (!hits) {
            status.textContent = 'No match for “' + input.value.trim() + '”. Try another word, or call 8776-0644 to 46 and we’ll point you the right way.';
            return;
        }
        var names = floorsHit.map(function (t) { return t.querySelector('.pdh-floor__num').textContent; });
        status.textContent = 'Found ' + hits + (hits === 1 ? ' place' : ' places') + ' on ' + (names.length === 1 ? 'floor ' : 'floors ') + names.join(', ') + '.';
        if (floorsHit.indexOf(tabs.filter(function (t) { return t.getAttribute('aria-selected') === 'true'; })[0]) === -1) select(floorsHit[0], false, false);
    }

    var timer;
    input.addEventListener('input', function () { clearTimeout(timer); timer = setTimeout(search, 150); });
    form.addEventListener('submit', function (ev) { ev.preventDefault(); search(); });

    var fromHash = tabs.filter(function (t) { return '#' + t.getAttribute('aria-controls') === location.hash; })[0];
    select(fromHash || tabs.filter(function (t) { return t.getAttribute('aria-selected') === 'true'; })[0] || tabs[0], false, false);
    var q = new URLSearchParams(location.search).get('q');
    if (q) { input.value = q; search(); }
})();
